window.__RESUME_PDF_B64 = "";
window.__openResume = function () {
  try {
    if (!window.__resumeUrl) {
      var bin = atob(window.__RESUME_PDF_B64);
      var arr = new Uint8Array(bin.length);
      for (var i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
      window.__resumeUrl = URL.createObjectURL(new Blob([arr], { type: 'application/pdf' }));
    }
    window.open(window.__resumeUrl, '_blank', 'noopener');
  } catch (e) { console.error('resume open failed', e); }
};
